pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(uint256 seed) public {
        // The admin is the deployer (this test contract); only admin calls complete.
        // Choose the new owner from a wide fuzzed domain; seed == 0 maps to the
        // CURRENT owner, the input class where the buggy unit returns false.
        address newOwner;
        if (seed == 0) {
            newOwner = c.owner();
        } else {
            newOwner = address(uint160(seed % type(uint160).max));
        }

        vm.prank(address(this));
        bool success = c.setOwner(newOwner);

        // General rule: any non-reverting admin setOwner reports success.
        assertTrue(success);
    }
}
